// ticks$ emits step indices from zero, one per fixed timeStep.
// Each subscription owns its angle history; drawPairs is the parsed tape.
angle$ = ticks$.pipe(
  scan((previousAngle, step) => {
    const [u, v] = drawPairs[step % drawPairs.length]
    const binomial = u - v
    const angle = wrapToSignedTurn(previousAngle + binomial * turnScale)
    return angle
  }, initialAngle),
  takeUntil(stop$) // stop$ emits when the study closes.
)
// The seed is remembered, not emitted; each tick emits the next angle.
// Small nudges make successive circle targets share a direction history.
// Feed each angle to the ordinary circle construction and velocity update.
// scan carries memory; limited acceleration still makes Nia’s motion gradual.
// This fold supplies neither the fixed clock nor wall avoidance.
